{"file_path":"tests/test_spec.py","content":""""Regression coverage for the behavior specified in SPEC.md."""

import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_none_counts_as_unflagged():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == pytest.approx(1 / 3)
    assert monitor_flag_rate([{"flagged": None}]) == 0.0


def test_monitor_flag_rate_empty():
    rate = monitor_flag_rate([])
    assert rate == 0.0
    assert isinstance(rate, float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}, {"flagged": None}, {"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_flag_rate_no_transcripts(groups):
    assert pooled_flag_rate(groups) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (1, 4), (2, 7), (3, 9), (10, 9)])
def test_flags_in_window(days, expected):
    assert flags_in_window([2, 3, 4], days) == expected


@pytest.mark.parametrize("days", [0, 1, 10])
def test_flags_in_window_empty(days):
    assert flags_in_window([], days) == 0


def test_parse_transcript_log_flags_whitespace_and_skipped_lines():
    lines = [
        "", " \t\n", "# comment", " \t# another,comment,ignored",
        " a , 2 , 1 \n", " b , -1 , 0 ", " c , 0 , \t",
    ]
    assert parse_transcript_log(iter(lines)) == [
        {"id": "a", "day": 2, "flagged": True},
        {"id": "b", "day": -1, "flagged": False},
        {"id": "c", "day": 0, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x,no,1", "x,1.5,0"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(["", " # comment", "valid,1,0", " \t", bad_line])


def test_dedupe_transcripts_keeps_last_duplicate_id_and_sorts():
    events = [
        {"id": "b", "day": 0, "flagged": True},
        {"id": "z", "day": 1, "flagged": True},
        {"id": "a", "day": 2, "flagged": False},
        {"id": "b", "day": 9, "flagged": True},
        {"id": "b", "day": 2, "flagged": None},
    ]
    assert dedupe_transcripts(events) == [events[1], events[2], events[4]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_inclusive_range_zeros_and_outside_events():
    events = [
        {"day": 0, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 1, "flagged": True},
        {"day": 2, "flagged": False},
        {"day": 2, "flagged": None},
        {"day": 4, "flagged": True},
        {"day": 5, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 1, 1) == [2]
    assert daily_flag_counts(events, 4, 1) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


def test_monitor_summary_pooled_rounding_calendar_window_and_nonempty_groups():
    groups = {
        "a": [{"day": 1, "flagged": True}],
        "b": [{"day": 4, "flagged": None}, {"day": 6, "flagged": False}],
        "empty": [],
    }
    assert monitor_summary(groups, 3) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 10) == {"rate": 0.333, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0)["recent"] == 0


def test_monitor_summary_counts_every_transcript_across_groups():
    event = {"id": "same", "day": 3, "flagged": True}
    assert monitor_summary({"a": [event], "b": [event]}, 1) == {
        "rate": 1.0, "recent": 2, "groups": 2,
    }


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_no_transcripts(groups):
    assert monitor_summary(groups, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}, {"flagged": False}],
        "empty": [],
        "a": [{"flagged": True}, {"flagged": None}],
        "best": [{"flagged": True}],
        "zero": [{"flagged": False}],
    }
    assert top_flagged_groups(groups, 2) == ["best", "a"]
    assert top_flagged_groups(groups, 10) == ["best", "a", "z", "zero"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({"empty": []}, 1) == []
    assert top_flagged_groups({}, 1) == []


def test_flag_rate_by_group_sorted_keys_and_empty_groups():
    result = flag_rate_by_group({
        "z": [{"flagged": True}, {"flagged": None}],
        "b": [{"flagged": False}],
        "a": [],
    })
    assert result == {"a": None, "b": 0.0, "z": 0.5}
    assert list(result) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize("counts, expected", [
    ([], 0),
    ([0, -1, 0], 0),
    ([1, 2, 0, 3, 4, 5, 0, 1], 3),
    ([1, -1, 2], 1),
    ([0, 1, 2, 3], 3),
])
def test_longest_flag_streak_positive_consecutive_entries(counts, expected):
    assert longest_flag_streak(counts) == expected
